const now = new Date();
const br = new Date(now.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const dia1111 = br.getMonth() === 10 && br.getDate() === 11 && br.getHours() >= 6; // 11/11: 6h à meia-noite
return [{ json: { hora_num: dia1111 ? 12 : br.getHours(), agora_br: br.toLocaleString('pt-BR') } }];

// Lê as palavras-chave do PERFIL no painel (fonte de verdade). Fallback = lista antiga.
const SECRET = "d9eb7e94067def9f8eb7e64e2b2d28cc93e092c62344a259e76682f9c1327235";
let KW = [];
try {
  const res = await this.helpers.httpRequest({
    method: "GET",
    url: "https://app.buscadorgeek.com.br/api/keywords/collector?slug=ofertas-maternas",
    headers: { "x-ingest-secret": SECRET },
    json: true,
  });
  if (res && Array.isArray(res.keywords)) KW = res.keywords;
} catch (e) {}
if (!KW.length) KW = ["fralda descartável","lenço umedecido","creme assadura","sabonete bebê","bebê conforto","brinquedo infantil","enxoval bebê","monitor bebê","banheira bebê","triciclo infantil","grade cama bebê","quarto bebê","copo infantil","touca bebê","prendedor chupeta","espelho carro bebê","garrafa térmica infantil","estante infantil","protetor solar infantil","chiqueirinho bebê"];
// fralda/lenço (melhor comissão) sorteados em ~35% das rodadas — decisão Bruno 08/Out (lista de keywords intacta)
const PRIOR = KW.filter(w => /fralda|len[cç]o/i.test(w));
const k = (PRIOR.length && Math.random() < 0.35) ? PRIOR[Math.floor(Math.random()*PRIOR.length)] : KW[Math.floor(Math.random()*KW.length)];
return [{ json: { keyword: k, row_number: 1 } }];

const appId = '18177790005';
const appSecret = 'DXQKJKMC5YY4JVHJJP5F4WF2ZOKEF7ZR';
const timestamp = Math.floor(Date.now() / 1000).toString();
const keyword = $input.first().json.keyword;
const keywordRow = $input.first().json.row_number;
// página 1–5 sorteada (19/Out): a página 1 dos mais vendidos já está toda no sistema → só deduplicava
const pagina = 1 + Math.floor(Math.random() * 5);
const graphqlQuery = '{ productOfferV2(listType: 0, sortType: 2, keyword: "' + keyword + '", page: ' + pagina + ', limit: 20) { nodes { itemId productName offerLink priceMin priceMax commissionRate sales ratingStar imageUrl shopName priceDiscountRate shopType } pageInfo { page limit hasNextPage } } }';
const body = JSON.stringify({ query: graphqlQuery });
return [{ json: { keyword, keyword_row: keywordRow, appId, timestamp, body, signString: appId + timestamp + body + appSecret } }];

const prepData = $('PREPARAR API SHOPEE').first().json;
const signature = $input.first().json.data;
const authHeader = 'SHA256 Credential=' + prepData.appId + ',Timestamp=' + prepData.timestamp + ',Signature=' + signature;
const result = await this.helpers.httpRequest({
  method: 'POST', url: 'https://open-api.affiliate.shopee.com.br/graphql',
  headers: { 'Content-Type': 'application/json', 'Authorization': authHeader },
  body: prepData.body, returnFullResponse: false, json: false, encoding: 'utf-8'
});
let parsed = typeof result === 'string' ? JSON.parse(result) : result;
return [{ json: { ...parsed, _keyword: prepData.keyword, _keyword_row: prepData.keyword_row } }];

const response = $input.first().json;
const keyword = response._keyword;
const keywordRow = response._keyword_row;
if (response.errors || !response.data || !response.data.productOfferV2) {
  return [{ json: { error: true, message: response.errors ? response.errors[0].message : 'No data', keyword, keyword_row: keywordRow, total_filtrado: 0, produtos: [] } }];
}
const nodes = response.data.productOfferV2.nodes || [];
const filtered = nodes.filter(p => {
  const commission = parseFloat(p.commissionRate) || 0;
  const rating = parseFloat(p.ratingStar) || 0;
  const sales = parseInt(p.sales) || 0;
  return commission >= 0.03 && rating >= 4.0 && sales >= 30;
});
return [{ json: { error: false, keyword, keyword_row: keywordRow, total_api: nodes.length, total_filtrado: filtered.length,
  produtos: filtered.map(p => ({
    item_id: String(p.itemId), product_name: p.productName, offer_link: p.offerLink,
    image_url: p.imageUrl, price_min: p.priceMin, price_max: p.priceMax,
    commission_rate: p.commissionRate, sales: String(p.sales), rating: p.ratingStar,
    shop_name: p.shopName, keyword, discount_rate: p.priceDiscountRate, shop_type: p.shopType
  }))
}}];

const items=$input.all(); const out=[];
function num(v){ const n=parseFloat(v); return isNaN(n)?null:n; }
for(const it of items){
  const produtos=it.json.produtos||[];
  for(const p of produtos){
    const url=p.offer_link;
    if(!url || String(url).indexOf('https://')!==0) continue;
    const pmin=num(p.price_min), pmax=num(p.price_max);
    out.push({ json:{
      source:'auto', source_ref:'shopee_'+p.item_id, platform:'shopee',
      url, affiliate_url:url,
      title:((p.product_name||'')+'').slice(0,500)||null,
      image_url:(typeof p.image_url==='string'&&p.image_url.indexOf('http')===0)?p.image_url:null,
      price_current:pmin, price_original:(pmax&&pmin&&pmax>pmin)?pmax:null, discount_pct:(p.discount_rate>0&&p.discount_rate<100)?p.discount_rate:null,
      perfil:'ofertas-maternas',
      promo_meta:(()=>{ const m={}; const r=parseFloat(p.rating); if(r>=4) m.rating=Math.round(r*10)/10;
        const s=parseInt(p.sales); if(s>=50) m.vendidos = s>=1000 ? '+'+(Math.floor(s/100)/10).toString().replace('.',',').replace(/,0$/,'')+' mil' : '+'+s;
        const st=[].concat(p.shop_type||[]); if(st.includes(1)) m.loja_oficial=true;
        return Object.keys(m).length?m:null; })()
    }});
  }
}
return out;
